page=O({'size':E('A4','A3','LETTER'),'orientation':E('portrait','landscape'),'margin':N(10,100),'columns':N(1,3),'header':S(240),'footer':S(240),'first_header':S(240),'even_header':S(240),'first_footer':S(240),'even_footer':S(240),'page_numbers':B,'break_before':B})
