sheet['description']='Row 1 is the header. Max 20000 workbook cells. Formula functions: SUM, AVERAGE, COUNT, COUNTA, MIN, MAX, IF, AND, OR, NOT, ROUND, ROUNDUP, ROUNDDOWN, ABS, COUNTIF, SUMIF, IFERROR, VLOOKUP, XLOOKUP, SUMIFS, COUNTIFS. Supplied cells only; no external/dynamic references. Merge covered cells must be empty. Chart/pivot ranges use same-sheet A1 notation; pivot destinations must be outside supplied data. Print margins in inches; image size in pixels.'
schema=O({'format':E('docx','pptx','xlsx','hwp','hwpx','pdf'),'title':S(240),'filename':S(80),'page':R('page'),'theme':O({'preset':E('business','minimal','dark'),'font':S(80),'accent':S(6),'background':S(6),'ratio':E('wide','standard')}),'sections':A(R('section'),80),'slides':A(R('slide'),40),'sheets':A(R('sheet'),8)},['format','title'])
